git status --short && git branch --show-current && cat > greet.py <<'EOF'
import sys


def _join_names(names: tuple[str, ...]) -> str:
    if len(names) == 1:
        return names[0]
    return ", ".join(names[:-1]) + " and " + names[-1]


def greet(*names: str) -> str:
    return f"Hello, {_join_names(names or ('world',))}!"


if __name__ == "__main__":
    print(greet(*sys.argv[1:]))
EOF
git add greet.py && git commit -q -m "TOY-002: greet multiple people

greet() now accepts any number of names, joined as \"A, B and C\".
No names defaults to \"world\"; the CLI greets every argument.

Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>" && cat >> test_greet.py <<'EOF'


def test_greet_no_names():
    assert greet() == "Hello, world!"


def test_greet_two_names():
    assert greet("Alice", "Bob") == "Hello, Alice and Bob!"


def test_greet_three_names():
    assert greet("Alice", "Bob", "Carol") == "Hello, Alice, Bob and Carol!"
EOF
python -m pytest -q 2>&1 | tail -3; python greet.py; python greet.py Bob; python greet.py Alice Bob; python greet.py Alice Bob Carol; python --version

